//! 📏️ Literal Generation relational census before typed native field ownership.
use super::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_dsl_record::NativeSchemaControl;
use semio_framework_dsl_record::FieldValue;
use semio_framework_dsl_record::RecordValue;
use semio_framework_value::DslValue;
use semio_framework_value::Number;
use semio_framework_artifact_flow_flow::{FlowUi,NodeChrome,neural::Tree};
struct Rows<'a,C>{control:&'a mut C,maximum:usize,count:usize,maximum_bytes:usize,bytes:usize}
impl<C:NativeSchemaControl> Rows<'_,C>{
 fn cells(&mut self,n:usize)->Result<(),ValueError>{self.bytes=self.bytes.checked_add(n).filter(|n|*n<=self.maximum_bytes).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Generation complete SQL semantic value bytes exceeded"))?;self.control.step()}
 fn text(&mut self,v:&str)->Result<(),ValueError>{self.cells(v.len())}
 fn float(&mut self,v:f64)->Result<(),ValueError>{self.cells(if v.is_nan(){11}else if v.is_infinite(){32}else{22})}
 fn texts<'a>(&mut self,values:impl IntoIterator<Item=&'a str>)->Result<(),ValueError>{for v in values{self.text(v)?;}Ok(())}
 fn add(&mut self,count:usize)->Result<(),ValueError>{self.count=self.count.checked_add(count).filter(|count|*count<=self.maximum).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit, "Generation semantic row limit exceeded"))?;self.control.step()}
 fn push<T>(&mut self,pending:&mut Vec<T>,value:T)->Result<(),ValueError>{if pending.len()==pending.capacity(){let growth=pending.capacity().max(1);let bytes=growth.checked_mul(std::mem::size_of::<T>()).filter(|bytes|*bytes<=isize::MAX as usize).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit, "Generation census frontier size overflow"))?;self.control.charge(bytes)?;pending.try_reserve_exact(growth).map_err(|_|ValueError::new(ValueRefusalKind::AllocationFailed,"Generation census frontier allocation failed"))?;}pending.push(value);Ok(())}
}
enum Owned<'a>{Dictionary(&'a Dictionary),Tree(&'a Tree),Gui(&'a FlowUi),Answer(&'a DslValue)}
pub(super) fn owned<C:NativeSchemaControl>(snapshot:&ControlledSnapshot,maximum:usize,maximum_bytes:usize,c:&mut C)->Result<usize,ValueError>{c.scoped_stage(|c|{c.begin_stage(0)?;let mut r=Rows{control:c,maximum,count:0,maximum_bytes,bytes:0};let mut pending=Vec::new();r.cells(24)?;r.text(&snapshot.host_snapshot.schema)?;for v in [snapshot.host_snapshot.camera.x,snapshot.host_snapshot.camera.y,snapshot.host_snapshot.camera.zoom]{r.float(v)?;}if let Some(v)=&snapshot.generation.selected_generation_id{r.text(v)?;}if let Some(v)=&snapshot.generation.preview_text{r.text(v)?;}for s in &snapshot.host_snapshot.synapses{r.cells(24)?;r.texts([s.id.as_str(),s.from.as_str(),s.to.as_str(),s.from_port.as_str(),s.to_port.as_str()])?;}for(k,v)in snapshot.host_snapshot.layout.iter(){r.cells(24)?;r.text(k)?;r.float(v.x)?;r.float(v.y)?;}r.add(2)?;r.add(snapshot.host_snapshot.synapses.len())?;r.add(snapshot.host_snapshot.layout.len())?;
 for widget in &snapshot.host_snapshot.widgets{r.add(2)?;owned_widget(&mut r,widget)?;match widget{
  Widget::Neuron{params,input_ports,output_ports,..}=>{r.add(input_ports.len())?;r.add(output_ports.len())?;r.push(&mut pending,Owned::Dictionary(params))?;},
  Widget::OutputPreview{preview,expanded,..}=>{r.add(expanded.len())?;r.push(&mut pending,Owned::Dictionary(preview))?;},
  Widget::Cluster{tree,flow,..}=>{r.push(&mut pending,Owned::Tree(tree))?;r.push(&mut pending,Owned::Gui(flow))?;},_=>{}
 }}
 for generation in &snapshot.generation.generations{r.add(1)?;r.cells(24)?;r.texts([generation.id.as_str(),generation.name.as_str()])?;for(key,value)in &generation.values{r.add(1)?;r.cells(32)?;r.text(key)?;r.push(&mut pending,Owned::Answer(value))?;}}
 while let Some(value)=pending.pop(){match value{
  Owned::Dictionary(value)=>{r.add(1)?;r.cells(8)?;for(key,value)in value.iter(){r.add(2)?;r.cells(40)?;r.text(key)?;match value{NeuralValue::Atom(Atom::Null)=>r.text("null")?,NeuralValue::Atom(Atom::Boolean(_))=>{r.text("boolean")?;r.cells(8)?;},NeuralValue::Atom(Atom::Integer(_))=>{r.text("integer")?;r.cells(8)?;},NeuralValue::Atom(Atom::Decimal(v))=>{r.text("decimal")?;r.float(*v)?;},NeuralValue::Atom(Atom::String(v))=>{r.text("string")?;r.text(v)?;},NeuralValue::Dictionary(_)=>{r.text("dictionary")?;r.cells(8)?;}}if let NeuralValue::Dictionary(value)=value{r.push(&mut pending,Owned::Dictionary(value))?;}}},
  Owned::Tree(value)=>{r.add(1)?;r.cells(8)?;r.add(value.synapses.len())?;for s in &value.synapses{r.cells(24)?;r.texts([s.id.as_str(),s.from.as_str(),s.to.as_str(),s.from_port.as_str(),s.to_port.as_str()])?;}for neuron in &value.neurons{r.add(1)?;r.cells(32+if neuron.tree.is_some(){8}else{0})?;r.texts([neuron.id.as_str(),neuron.kind.as_str()])?;r.push(&mut pending,Owned::Dictionary(&neuron.params))?;if let Some(child)=&neuron.tree{r.push(&mut pending,Owned::Tree(child))?;}}},
  Owned::Gui(value)=>{owned_gui(&mut r,value)?;r.add(1)?;for _ in value.nodes.iter(){r.add(2)?;}for preview in &value.previews{r.add(1)?;r.add(preview.expanded.len())?;r.push(&mut pending,Owned::Dictionary(&preview.preview))?;}},
  Owned::Answer(value)=>{r.add(1)?;answer_cells(&mut r,value)?;match value{semio_framework_value::DslValue::Array(values)=>for value in values{r.add(1)?;r.cells(32)?;r.push(&mut pending,Owned::Answer(value))?;},semio_framework_value::DslValue::Object(values)=>for(key,value)in values{r.add(1)?;r.cells(32)?;r.text(key)?;r.push(&mut pending,Owned::Answer(value))?;},_=>{}}}
 }}Ok(r.count)
})}
fn field(record:&RecordValue,id:u16)->Result<&FieldValue,ValueError>{record.fields.get(&id).ok_or(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census field missing"))}
fn record(value:&FieldValue)->Result<&RecordValue,ValueError>{match value{semio_framework_dsl_record::FieldValue::Record(value)=>Ok(value),semio_framework_dsl_record::FieldValue::Block(value)=>record(value),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census record differs"))}}
fn list(value:&FieldValue)->Result<&[FieldValue],ValueError>{match value{semio_framework_dsl_record::FieldValue::List(value)=>Ok(value),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census list differs"))}}
fn map(value:&FieldValue)->Result<&[(String,FieldValue)],ValueError>{match value{semio_framework_dsl_record::FieldValue::Map(value)=>Ok(value),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census map differs"))}}
fn dynamic(value:&FieldValue)->Result<&DslValue,ValueError>{match value{semio_framework_dsl_record::FieldValue::Value(value)=>Ok(value),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census intrinsic value differs"))}}
fn optional(value:Option<&FieldValue>)->Option<&FieldValue>{value.filter(|v|!matches!(v,FieldValue::Absent))}
fn member<'a>(value:&'a DslValue,key:&str)->Result<&'a DslValue,ValueError>{let semio_framework_value::DslValue::Object(values)=value else{return Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census object differs"))};let mut found=values.iter().filter(|(k,_)|k==key);let value=&found.next().ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue, "Generation census member missing"))?.1;if found.next().is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census member repeated"))}Ok(value)}
fn array(value:&DslValue)->Result<&[DslValue],ValueError>{match value{semio_framework_value::DslValue::Array(values)=>Ok(values),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census array differs"))}}
fn object(value:&DslValue)->Result<&[(String,DslValue)],ValueError>{match value{semio_framework_value::DslValue::Object(values)=>Ok(values),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census object differs"))}}
enum Borrowed<'a>{Dictionary(&'a[FieldValue]),DynamicDictionary(&'a DslValue),Tree(&'a DslValue),Gui(&'a DslValue),Answer(&'a DslValue)}
pub(super) fn borrowed<C:NativeSchemaControl>(source:&RecordValue,maximum:usize,maximum_bytes:usize,c:&mut C)->Result<usize,ValueError>{c.scoped_stage(|c|{c.begin_stage(0)?;let mut r=Rows{control:c,maximum,count:0,maximum_bytes,bytes:0};let mut pending=Vec::new();r.cells(24)?;r.text(text(field(source,0)?)?)?;float_record(&mut r,record(field(source,1)?)?,&[0,1,2])?;for id in [5,6]{if let Some(v)=optional(source.fields.get(&id)){r.text(text(v)?)?;}}for s in list(field(source,3)?)?{let s=record(s)?;r.cells(24)?;r.text(text(field(s,0)?)?)?;let FieldValue::Wire(w)=field(s,1)? else{return Err(invalid())};r.text(&w.from.id)?;if let Some(v)=&w.from.port{r.text(v)?;}if let Some((_,to))=&w.edge{r.text(&to.id)?;if let Some(v)=&to.port{r.text(v)?;}}}for(k,v)in map(field(source,4)?)?{r.cells(24)?;r.text(k)?;float_record(&mut r,record(v)?,&[0,1])?;}r.add(2)?;r.add(list(field(source,3)?)?.len())?;r.add(map(field(source,4)?)?.len())?;
 let widgets=match field(source,2)?{semio_framework_dsl_record::FieldValue::Block(value)=>match value.as_ref(){semio_framework_dsl_record::FieldValue::Statements(values)=>values,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census statements differ"))},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census widget block differs"))};
 for(kind,widget)in widgets{r.add(2)?;borrowed_widget(&mut r,kind,widget)?;match kind.as_str(){
  "neuron"=>{r.add(list(field(widget,3)?)?.len())?;r.add(list(field(widget,4)?)?.len())?;r.push(&mut pending,Borrowed::Dictionary(list(field(widget,5)?)?))?;},
  "output-preview"=>{r.add(list(field(widget,2)?)?.len())?;r.push(&mut pending,Borrowed::Dictionary(list(field(widget,1)?)?))?;},
  "cluster"=>{r.push(&mut pending,Borrowed::Tree(dynamic(field(widget,2)?)?))?;r.push(&mut pending,Borrowed::Gui(dynamic(field(widget,3)?)?))?;},
  "input-slider"|"input-note"|"input-image"|"variable"|"output-action"|"output-export"=>{},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue, "Generation census widget kind differs"))
 }}
 for generation in list(field(source,7)?)?{r.add(1)?;let g=record(generation)?;r.cells(24)?;r.text(text(field(g,0)?)?)?;r.text(text(field(g,1)?)?)?;for(key,value)in map(field(g,2)?)?{r.add(1)?;r.cells(32)?;r.text(key)?;r.push(&mut pending,Borrowed::Answer(dynamic(value)?))?;}}
 while let Some(value)=pending.pop(){match value{
  Borrowed::Dictionary(entries)=>{r.add(1)?;r.cells(8)?;for entry in entries{r.add(2)?;let entry=record(entry)?;r.cells(40)?;r.text(text(field(entry,0)?)?)?;let value=record(field(entry,1)?)?;neural_fields(&mut r,value)?;if let Some(value)=optional(value.fields.get(&5)){r.push(&mut pending,Borrowed::Dictionary(list(value)?))?;}}},
  Borrowed::DynamicDictionary(value)=>{r.add(1)?;r.cells(8)?;for(key,value)in object(value)?{r.add(2)?;r.cells(40)?;r.text(key)?;neural_dynamic(&mut r,value)?;if matches!(value,DslValue::Object(_)){r.push(&mut pending,Borrowed::DynamicDictionary(value))?;}}},
  Borrowed::Tree(value)=>{r.add(1)?;r.cells(8)?;r.add(array(member(value,"synapses")?)?.len())?;for s in array(member(value,"synapses")?)?{r.cells(24)?;for name in ["id","from","to","fromPort","toPort"]{r.text(dynamic_text(member(s,name)?)?)?;}}for neuron in array(member(value,"neurons")?)?{r.add(1)?;r.cells(32+if matches!(member(neuron,"tree")?,DslValue::Null){0}else{8})?;r.text(dynamic_text(member(neuron,"id")?)?)?;r.text(dynamic_text(member(neuron,"kind")?)?)?;r.push(&mut pending,Borrowed::DynamicDictionary(member(neuron,"params")?))?;let child=member(neuron,"tree")?;if !matches!(child,DslValue::Null){r.push(&mut pending,Borrowed::Tree(child))?;}}},
  Borrowed::Gui(value)=>{borrowed_gui(&mut r,value)?;r.add(1)?;for _ in object(member(value,"nodes")?)?{r.add(2)?;}for preview in array(member(value,"previews")?)?{r.add(1)?;r.add(array(member(preview,"expanded")?)?.len())?;r.push(&mut pending,Borrowed::DynamicDictionary(member(preview,"preview")?))?;}},
  Borrowed::Answer(value)=>{r.add(1)?;answer_cells(&mut r,value)?;match value{semio_framework_value::DslValue::Array(values)=>for value in values{r.add(1)?;r.cells(32)?;r.push(&mut pending,Borrowed::Answer(value))?;},semio_framework_value::DslValue::Object(values)=>for(key,value)in values{r.add(1)?;r.cells(32)?;r.text(key)?;r.push(&mut pending,Borrowed::Answer(value))?;},_=>{}}}
 }}Ok(r.count)
})}

fn invalid()->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,"Generation semantic SQL field shape differs")}
fn text(v:&FieldValue)->Result<&str,ValueError>{match v{FieldValue::Text(v)=>Ok(v),_=>Err(invalid())}}
fn dynamic_text(v:&DslValue)->Result<&str,ValueError>{match v{DslValue::String(v)=>Ok(v),_=>Err(invalid())}}
fn dynamic_float(v:&DslValue)->Result<f64,ValueError>{match v{DslValue::Number(v)=>Ok(v.as_f64()),_=>Err(invalid())}}
fn float_record<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&RecordValue,ids:&[u16])->Result<(),ValueError>{for id in ids{let FieldValue::Float(v)=field(v,*id)? else{return Err(invalid())};r.float(*v)?;}Ok(())}
fn dynamic_floats<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&DslValue,names:&[&str])->Result<(),ValueError>{for name in names{r.float(dynamic_float(member(v,name)?)?)?;}Ok(())}
fn digits(mut v:u64)->usize{let mut n=1;while v>=10{v/=10;n+=1;}n}
fn answer_cells<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&DslValue)->Result<(),ValueError>{r.cells(8)?;match v{DslValue::Null=>r.text("null"),DslValue::Bool(_)=>{r.text("boolean")?;r.cells(8)},DslValue::Number(Number::UInt(v))=>{r.text("unsigned")?;r.cells(digits(*v))},DslValue::Number(Number::Int(_))=>{r.text("integer")?;r.cells(8)},DslValue::Number(Number::Float(v))=>{r.text("float")?;r.float(*v)},DslValue::String(v)=>{r.text("string")?;r.text(v)},DslValue::Bytes(v)=>{r.text("bytes")?;r.cells(v.len())},DslValue::Array(_)=>r.text("array"),DslValue::Object(_)=>r.text("object")}}
fn neural_dynamic<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&DslValue)->Result<(),ValueError>{match v{DslValue::Null=>r.text("null"),DslValue::Bool(_)=>{r.text("boolean")?;r.cells(8)},DslValue::Number(Number::Int(_)|Number::UInt(_))=>{r.text("integer")?;r.cells(8)},DslValue::Number(Number::Float(v))=>{r.text("decimal")?;r.float(*v)},DslValue::String(v)=>{r.text("string")?;r.text(v)},DslValue::Object(_)=>{r.text("dictionary")?;r.cells(8)},_=>Err(invalid())}}
fn neural_fields<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&RecordValue)->Result<(),ValueError>{let mut found=0;for id in 0..6{if let Some(v)=optional(v.fields.get(&id)){found+=1;match(id,v){(0,FieldValue::Bool(_))=>r.text("null")?,(1,FieldValue::Bool(_))=>{r.text("boolean")?;r.cells(8)?;},(2,FieldValue::Int(_))=>{r.text("integer")?;r.cells(8)?;},(3,FieldValue::Float(v))=>{r.text("decimal")?;r.float(*v)?;},(4,FieldValue::Text(v))=>{r.text("string")?;r.text(v)?;},(5,FieldValue::List(_))=>{r.text("dictionary")?;r.cells(8)?;},_=>return Err(invalid())}}}if found!=1{return Err(invalid())}Ok(())}
fn owned_widget<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&Widget)->Result<(),ValueError>{r.cells(24)?;let(kind,id)=match v{Widget::Neuron{id,..}=>("neuron",id),Widget::InputSlider{id,..}=>("input_slider",id),Widget::InputNote{id,..}=>("input_note",id),Widget::InputImage{id,..}=>("input_image",id),Widget::Variable{id,..}=>("variable",id),Widget::OutputPreview{id,..}=>("output_preview",id),Widget::OutputAction{id,..}=>("output_action",id),Widget::OutputExport{id,..}=>("output_export",id),Widget::Cluster{id,..}=>("cluster",id)};r.texts([kind,id.as_str()])?;match v{
Widget::Neuron{neuron_kind,input_ports,output_ports,..}=>{r.cells(24)?;r.text(neuron_kind)?;for(dir,ports)in [("input",input_ports),("output",output_ports)]{for name in ports{r.cells(24)?;r.texts([dir,name.as_str()])?;}}},
Widget::InputSlider{label,value,min,max,step,..}=>{r.cells(8)?;r.text(label)?;for v in [value,min,max,step]{r.float(*v)?;}},
Widget::InputNote{text,..}=>{r.cells(8)?;r.text(text)?;},Widget::InputImage{src,..}=>{r.cells(8)?;r.text(src)?;},Widget::Variable{name,schema,..}=>{r.cells(8)?;r.texts([name.as_str(),schema.as_str()])?;},
Widget::OutputPreview{expanded,..}=>{r.cells(16)?;for path in expanded.iter(){r.cells(24)?;r.text(path)?;}},Widget::OutputAction{action,..}=>{r.cells(8)?;r.text(action)?;},Widget::OutputExport{format,..}=>{r.cells(8)?;r.text(format)?;},Widget::Cluster{name,..}=>{r.cells(24)?;r.text(name)?;}}
Ok(())}
fn borrowed_widget<C:NativeSchemaControl>(r:&mut Rows<'_,C>,kind:&str,v:&RecordValue)->Result<(),ValueError>{let sql_kind=match kind{"neuron"=>"neuron","input-slider"=>"input_slider","input-note"=>"input_note","input-image"=>"input_image","variable"=>"variable","output-preview"=>"output_preview","output-action"=>"output_action","output-export"=>"output_export","cluster"=>"cluster",_=>return Err(invalid())};r.cells(24)?;r.texts([sql_kind,text(field(v,0)?)?])?;match kind{
"neuron"=>{r.cells(24)?;r.text(text(field(v,1)?)?)?;for(id,dir)in[(3,"input"),(4,"output")]{for name in list(field(v,id)?)?{r.cells(24)?;r.texts([dir,text(name)?])?;}}},
"input-slider"=>{r.cells(8)?;r.text(text(field(v,1)?)?)?;float_record(r,v,&[2,3,4,5])?;},
"variable"=>{r.cells(8)?;r.text(text(field(v,1)?)?)?;r.text(text(field(v,2)?)?)?;},
"input-note"|"input-image"|"output-action"|"output-export"=>{r.cells(8)?;r.text(text(field(v,1)?)?)?;},
"output-preview"=>{r.cells(16)?;for path in list(field(v,2)?)?{r.cells(24)?;r.text(text(path)?)?;}},"cluster"=>{r.cells(24)?;r.text(text(field(v,1)?)?)?;},_=>return Err(invalid())}Ok(())}
fn owned_gui<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&FlowUi)->Result<(),ValueError>{r.cells(8)?;for v in [v.camera.x,v.camera.y,v.camera.zoom]{r.float(v)?;}for(name,n)in v.nodes.iter(){r.cells(24)?;r.text(name)?;r.float(n.layout.x)?;r.float(n.layout.y)?;match &n.chrome{NodeChrome::Plain{..}=>{r.text("plain")?;r.cells(16)?;},NodeChrome::Slider{label,min,max,step,value}=>{r.text("slider")?;r.cells(8)?;r.text(label)?;for v in [min,max,step,value]{r.float(*v)?;}},NodeChrome::Note{text}=>{r.text("note")?;r.cells(8)?;r.text(text)?;},NodeChrome::Image{src}=>{r.text("image")?;r.cells(8)?;r.text(src)?;},NodeChrome::Variable{name,schema}=>{r.text("variable")?;r.cells(8)?;r.texts([name.as_str(),schema.as_str()])?;}}}for p in &v.previews{r.cells(32)?;r.texts([p.id.as_str(),p.mode.as_str()])?;if let Some(s)=&p.source{r.texts([s.neuron.as_str(),s.channel.as_str()])?;}if let Some(v)=&p.layout{r.float(v.x)?;r.float(v.y)?;}for path in p.expanded.iter(){r.cells(24)?;r.text(path)?;}}Ok(())}
fn borrowed_gui<C:NativeSchemaControl>(r:&mut Rows<'_,C>,v:&DslValue)->Result<(),ValueError>{r.cells(8)?;dynamic_floats(r,member(v,"camera")?,&["x","y","zoom"])?;for(name,n)in object(member(v,"nodes")?)?{r.cells(24)?;r.text(name)?;dynamic_floats(r,member(n,"layout")?,&["x","y"])?;let c=member(n,"chrome")?;let kind=dynamic_text(member(c,"kind")?)?;r.text(kind)?;match kind{"plain"=>r.cells(16)?,"slider"=>{r.cells(8)?;r.text(dynamic_text(member(c,"label")?)?)?;dynamic_floats(r,c,&["min","max","step","value"])?;},"note"|"image"=>{r.cells(8)?;r.text(dynamic_text(member(c,if kind=="note"{"text"}else{"src"})?)?)?;},"variable"=>{r.cells(8)?;r.text(dynamic_text(member(c,"name")?)?)?;r.text(dynamic_text(member(c,"schema")?)?)?;},_=>return Err(invalid())}}for p in array(member(v,"previews")?)?{r.cells(32)?;r.text(dynamic_text(member(p,"id")?)?)?;r.text(dynamic_text(member(p,"mode")?)?)?;let s=member(p,"source")?;if !matches!(s,DslValue::Null){r.text(dynamic_text(member(s,"neuron")?)?)?;r.text(dynamic_text(member(s,"channel")?)?)?;}let layout=member(p,"layout")?;if !matches!(layout,DslValue::Null){dynamic_floats(r,layout,&["x","y"])?;}for path in array(member(p,"expanded")?)?{r.cells(24)?;r.text(dynamic_text(path)?)?;}}Ok(())}
